import json,copy,re
P='../data/question-bank.json'
B=json.load(open('question-bank.before-review.json',encoding='utf8'))   # always start from the pre-review snapshot
Q={q['id']:q for s in B['sessions'] for q in s['questions']}
LOG=[]
def chg(i,field,new,reason):
    old=Q[i].get(field) if field in Q[i] else None
    if old!=new:
        LOG.append({'id':i,'field':field,'before':copy.deepcopy(old),'after':copy.deepcopy(new),'reason':reason}); Q[i][field]=new
V=json.load(open('quran_verified.json',encoding='utf8'))
def uth(seg):
    seg=seg.replace('ࣰ','ً').replace('ࣱ','ٌ').replace('ࣲ','ٍ')
    seg=re.sub('[ۖ-ۜ\s]+$','',seg)
    return '﴿'+seg+'﴾'
VK={'s1q2':'s1q2','s3q2':'s3q2','s4q4':['s4q4a','s4q4b'],'s5q3':'s5q3','s5q4':'s5q4','s6q3':'s6q3','s8q1':'s8q1','s9q1':'s9q1','s10q1':'s10q1'}
QSRC="مطابق لنص مصحف رقمي مفتوح (fawazahmed0/quran-api، الإصدار ara-quranuthmanienc)، وتطابق الهيكل الحرفي مع مجموعة ثانية (semarketir/quranjson). التشكيل مأخوذ من المجموعة الأولى كما هو، وحُوّلت علامات التنوين المفتوح إلى التنوين العادي لدعم الخط. بانتظار مطابقة المشرف بمصحف المدينة."
for qid,keys in VK.items():
    keys=keys if isinstance(keys,list) else [keys]
    new=copy.deepcopy(Q[qid]['nass'])
    ai=0
    for n in new:
        if n['k']!='آية': continue
        v=V[keys[ai]]; ai+=1
        n['t']=uth(v['uthmani']); n['verify']=QSRC; n['dataset_ref']=f"{v['chapter']}:{v['verse']}"
    chg(qid,'nass',new,'استبدال نص الآية بنص المصحف الرقمي المتحقق منه (التشكيل والرسم العثماني)')
